static void clk_range_test_multiple_disjoints_range ( struct kunit * test ) { struct clk_dummy_context * ctx = test -> priv ; struct clk_hw * hw = & ctx -> hw ; struct clk * user1 , * user2 ; user1 = clk_hw_get_clk ( hw , NULL ) ; KUNIT_ASSERT_NOT_ERR_OR_NULL ( test , user1 ) ; user2 = clk_hw_get_clk ( hw , NULL ) ; KUNIT_ASSERT_NOT_ERR_OR_NULL ( test , user2 ) ; KUNIT_EXPECT_LT ( test , clk_set_rate_range ( user2 , 3000 , 4000 ) , 0 ) ; clk_put ( user2 ) ; clk_put ( user1 ) ; } 